def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = []
    for word in words:
        sorted_words.append(''.join(sorted(word)))
    return ' '.join(sorted_words)

def next_smallest(lst):
    unique_sorted = sorted(set(lst))
    return unique_sorted[1] if len(unique_sorted) > 1 else None

def minPath(grid, k):
    from heapq import heappop, heappush
    from collections import defaultdict

    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up
    min_heap = []
    visited = set()

    # Initialize the heap with all cells in the grid
    for r in range(N):
        for c in range(N):
            heappush(min_heap, (grid[r][c], [(grid[r][c])], r, c))

    while min_heap:
        value, path, r, c = heappop(min_heap)
        if len(path) == k:
            return path
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                new_value = grid[nr][nc]
                new_path = path + [new_value]
                heappush(min_heap, (new_value, new_path, nr, nc))

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))
    indexed_nums = list(enumerate(nums))
    sorted_indexed = sorted(indexed_nums, key=lambda x: (digit_sum(x[1]), x[0]))
    return [num for index, num in sorted_indexed]

def x_or_y(n, x, y):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
    return x if is_prime(n) else y

import hashlib

def string_to_md5(text):
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
